INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:dbc4c1228ac85ceb5398db8fff:bab_nasara', 'dbc4c1228ac85ceb5398db8fff', 'WZ:faala_yafulu', 'GT:form_family:bab_nasara', NULL, 'قَالَ يَقُولُ', 'bab_nasara', 'mutaaddi', 'source_attested', 'high', 0, NULL, 'jawhari_sihah', 'blk_sih_2c7ec824fcd4eda6 p.3577 (past in a: قَوَلْتُ); blk_sih_73395dee9703d0fa p.3577 («قال يقول قولاً، وقَوْلَةً، ومَقالاً، ومقالَةً»); al-Miṣbāḥ blk_msb_1010ee9d1de9df2a p.2555 («قَالَ يَقُولُ قَوْلًا وَمَقَالًا وَمَقَالَةً»)', 'وأصلُ قلتُ قَوَلْتُ بالفتح، ولا يجوز أن يكون بالضم، لأنه يَتَعدَّى', 'live', 'GT:jumud:fil', 'GT:transitivity:transitive');
INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:b519a30933af9118c2a4bfb129:masdar', 'b519a30933af9118c2a4bfb129', 'WZ:fal', 'GT:derivation_type:masdar', NULL, 'قَالَ يَقُولُ', 'bab_nasara', 'mutaaddi', 'source_attested', 'high', 0, NULL, 'qamus_muhit', 'blk_qms_dbb270b2b54cca7d (no printed page); al-Miṣbāḥ blk_msb_1010ee9d1de9df2a p.2555 («قَالَ يَقُولُ قَوْلًا وَمَقَالًا وَمَقَالَةً»); Maqāyīs blk_mqy_a7fc735a606ee41c p.8 («يُقال: قَالَ يقول قَولاً»)', 'أو القَوْلُ مَصْدَرٌ، والقيلُ والقالُ اسْمانِ له', 'live', 'GT:jumud:mushtaqq', 'GT:transitivity:transitive');
INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:45cf5dfc844ffea30985b8699b:actpcpl', '45cf5dfc844ffea30985b8699b', 'WZ:faail', 'GT:derivation_type:active_participle', 'WZR:faail:actpcpl:default', 'قَالَ يَقُولُ', 'bab_nasara', 'mutaaddi', 'source_attested', 'high', 0, NULL, 'ibn_manzur_lisan_arab', 'blk_lsn_7d46b992597c0b64 p.4737; al-Qāmūs blk_qms_dbb270b2b54cca7d no printed page («فهو قائِلٌ وقالٌ وقَؤُولٌ»)', 'تَقُولُ: قَالَ يَقُولُ قَولًا، وَالْفَاعِلُ قَائِل، وَالْمَفْعُولُ مَقُول', 'live', 'GT:jumud:mushtaqq', 'GT:transitivity:transitive');
INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:5d129109aa4d540e684518fd62:masdar', '5d129109aa4d540e684518fd62', 'WZ:fil', 'GT:derivation_type:masdar', NULL, 'قَالَ يَقُولُ', 'bab_nasara', 'mutaaddi', 'source_attested', 'medium', 1, 'Lisān lists قِيل with the verbal nouns (مصادر) of قَالَ; al-Miṣbāḥ (after Ibn al-Sikkīt) calls قِيل and قَال nouns from it, not مصادر; al-Qāmūs gives both views. al-Rāghib: «القَوْلُ والقِيلُ واحد».', 'ibn_manzur_lisan_arab', 'blk_lsn_a9abb665776f8d2a p.4737; al-Miṣbāḥ blk_msb_1010ee9d1de9df2a p.2555 («وَالْقَالُ وَالْقِيلُ اسْمَانِ مِنْهُ لَا مَصْدَرَانِ»); al-Qāmūs blk_qms_dbb270b2b54cca7d no printed page («أو القَوْلُ مَصْدَرٌ، والقيلُ والقالُ اسْمانِ له»); al-Rāghib blk_mfr_a5a15ef673670b0d p.688 («القَوْلُ والقِيلُ واحد»)', 'قَالَ يَقُولُ قَوْلًا وقِيلًا وقَوْلةً ومَقالًا ومَقالةً', 'live', 'GT:jumud:mushtaqq', 'GT:transitivity:transitive');
INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:fb70ffa1155199876c5f8390a9:form_v', 'fb70ffa1155199876c5f8390a9', 'WZ:tafaala_yatafaalu', 'GT:form_family:form_v', NULL, 'تَقَوَّلَ يَتَقَوَّلُ', NULL, 'mutaaddi', 'source_attested', 'high', 0, NULL, 'qamus_muhit', 'blk_qms_dbb270b2b54cca7d (no printed page); Lisān blk_lsn_21f08641a3972f36 p.4737 («وتَقَوَّلَ قَوْلًا: ابتدَعه كذِباً. وتَقَوَّلَ فُلَانٌ عليَّ بَاطِلًا أَي قَالَ عَليَّ مَا لَمْ أَكن قلتُ وَكَذِبَ عليَّ؛ وَمِنْهُ قَوْلُهُ تَعَالَى: وَلَوْ تَقَوَّلَ عَلَيْنا بَعْضَ الْأَقاوِيلِ»); Qurʾān 52:33 (تَقَوَّلَهُ, with a direct object)', 'وتَقَوَّلَ قَوْلاً: ابتَدَعه كذِباً', 'live', 'GT:jumud:fil', 'GT:transitivity:transitive');
INSERT INTO ar_ling_root_lemma_wazn (id, lemma_id, wazn_id, gram_term_ref, rule_id, base_verb, base_bab, transitivity, basis, confidence, is_disputed, dispute_note, source_slug, source_ref, quote_ar, status, jumud_ref, transitivity_ref) VALUES ('LW:d2d1c95d37456b22f8850bdb7f:jam', 'd2d1c95d37456b22f8850bdb7f', 'WZ:afail_pl', 'GT:noun_process:jam_taksir', NULL, NULL, NULL, NULL, 'source_attested', 'high', 1, 'Lisān and al-Qāmūs: a plural of أَقْوَال, so a plural of a plural. al-Zamakhsharī (69:44) also allows it as if from أُفْعُولَة, a form that belittles the made-up sayings.', 'ibn_manzur_lisan_arab', 'blk_lsn_a9abb665776f8d2a p.4737; al-Qāmūs blk_qms_dbb270b2b54cca7d no printed page («ج: أقْوالٌ. جج: أقاويلٌ»); al-Zamakhsharī QR:TE:176eecc4c90171accb45a2a0 at 69:44 («وسمى الأقوال المتقولة «أقاويل» تصغيرا بها وتحقيرا»)', 'وَالْجَمْعُ أَقْوال، وأَقاوِيل جَمْعُ الْجَمْعِ', 'live', NULL, NULL);
INSERT INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, name_en, root_id, lemma_id) VALUES ('PAR:قول:I', 'قَالَ يَقُولُ', 'verb_form', 'I', 'hollow_w', '{"past": "قَالَ", "present": "يَقُولُ", "masadir": ["قَوْلًا", "قَوْلَةً", "مَقَالًا", "مَقَالَةً"], "active_participle": "قَائِلٌ", "active_participle_gt": "GT:derivation_type:active_participle", "passive_past": "قِيلَ", "passive_present": "يُقَالُ", "passive_participle": "مَقُولٌ", "imperative": "قُلْ", "prohibition": "لَا تَقُلْ", "derived": [{"word": "قَوَّالٌ", "gt": "GT:derivation_type:mubalagha", "pattern": "فَعَّال", "meaning": "someone who talks a lot"}], "meaning": "to say", "note": "Hollow verb: the و shows in يَقُولُ and drops in قُلْ، قُلْتُ. Verbal nouns from al-Ṣiḥāḥ and al-Miṣbāḥ; Lisān adds قِيلًا, which al-Miṣbāḥ counts as a plain noun, not a verbal noun.", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:hollow_w", "route_gt": "GT:taddiya_route:binafsihi", "quran_n": 1618, "cite": {"surah": 2, "ayah": 30, "needle": "قال ربك للملائكة"}, "full_table": true, "source_ref": "PAR:template:I:hollow_w:nasara; al-Ṣiḥāḥ blk_sih_73395dee9703d0fa p.3577 (verbal nouns), blk_sih_2c7ec824fcd4eda6 (verb class: past in a, takes an object); al-Miṣbāḥ blk_msb_1010ee9d1de9df2a p.2555; Maqāyīs blk_mqy_a7fc735a606ee41c p.8 (قَوَّال) (checked against the muṣḥaf and the lexicons)"}', NULL, 'kmaps_synth', 'PAR:template:I:hollow_w:nasara; al-Ṣiḥāḥ blk_sih_73395dee9703d0fa p.3577 (verbal nouns), blk_sih_2c7ec824fcd4eda6 (verb class: past in a, takes an object); al-Miṣbāḥ blk_msb_1010ee9d1de9df2a p.2555; Maqāyīs blk_mqy_a7fc735a606ee41c p.8 (قَوَّال)', 'bab_nasara', 'live', 'to say', '58adcb34a9f5ad358ca4df9c7e', 'dbc4c1228ac85ceb5398db8fff');
INSERT INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, name_en, root_id, lemma_id) VALUES ('PAR:قول:V', 'تَقَوَّلَ يَتَقَوَّلُ', 'verb_form', 'V', 'hollow_w', '{"past": "تَقَوَّلَ", "present": "يَتَقَوَّلُ", "masadir": ["تَقَوُّلًا"], "active_participle": "مُتَقَوِّلٌ", "active_participle_gt": "GT:derivation_type:active_participle", "passive_past": "تُقُوِّلَ", "passive_present": "يُتَقَوَّلُ", "passive_participle": "مُتَقَوَّلٌ", "imperative": "تَقَوَّلْ", "prohibition": "لَا تَتَقَوَّلْ", "meaning": "to make up words and say someone said them", "note": "Acts like a sound verb: the doubled و stays. al-Zamakhsharī at 69:44: the form carries effort, «كأن فيه تكلفا». Takes a direct object (52:33) or عَلَى + object (69:44).", "form_gt": "GT:form_family:form_v", "root_type_gt": "GT:root_type:hollow_w", "route_gt": "GT:taddiya_route:binafsihi", "quran_n": 2, "cite": {"surah": 69, "ayah": 44, "needle": "ولو تقول علينا بعض الاقاويل"}, "full_table": false, "source_ref": "PAR:template:V:hollow; al-Qāmūs blk_qms_dbb270b2b54cca7d; Lisān blk_lsn_21f08641a3972f36 p.4737; al-Zamakhsharī QR:TE:176eecc4c90171accb45a2a0 (69:44) and QR:TE:c80f8c7e5d34d7759b86bc0a (52:33, «بمتقول») (checked against the muṣḥaf and the lexicons)"}', NULL, 'kmaps_synth', 'PAR:template:V:hollow; al-Qāmūs blk_qms_dbb270b2b54cca7d; Lisān blk_lsn_21f08641a3972f36 p.4737; al-Zamakhsharī QR:TE:176eecc4c90171accb45a2a0 (69:44) and QR:TE:c80f8c7e5d34d7759b86bc0a (52:33, «بمتقول»)', NULL, 'live', 'to make up words and say someone said them', '58adcb34a9f5ad358ca4df9c7e', 'fb70ffa1155199876c5f8390a9');
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:cmb1', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'root', 'قول', 'cmb1', 'القَوْلُ من النُّطق', 'speaking: words put into sound', 'النُّطق', 'speaking aloud', 'combined rungs 1–2: Ibn Fāris «وهو القَول من النُّطق»; al-Rāghib, Lisān, al-Qāmūs and Lane give the same head sense.', 1, 1, '[{"source": "maqayis_lugha", "block": "blk_mqy_a7fc735a606ee41c", "page": "p.8", "quote_ar": "وهو القَول من النُّطق"}, {"source": "raghib_mufradat", "block": "blk_mfr_3ba74d8a48bcfaaa", "page": "p.688", "quote_ar": "أظهرها أن يكون للمركّب من الحروف المبرز بالنّطق، مفردا كان أو جملة"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "القَوْل: الْكَلَامُ عَلَى التَّرْتِيبِ، وَهُوَ عِنْدَ المحقِّق كُلُّ لَفْظٍ قَالَ بِهِ اللِّسَانُ، تَامًّا كَانَ أَو نَاقِصًا"}, {"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "القَوْلُ: الكَلامُ، أو كُلُّ لَفْظٍ مَذَلَ به اللِسانُ، تامّاً أو ناقِصاً"}, {"source": "lane_lexicon", "block": "blk_lane_eead26a3e20fe2d5", "page": "p.2995", "quote_en": "A saying; something said: and speech, or diction"}]', 0.95, 'lexicon_layers_2026_10_07', 'combined', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:cmb3', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'root', 'قول', 'cmb3', 'القَوْلُ على أحدٍ بالكذب', 'saying something false against someone', 'القول على', 'saying against', 'combined rungs 3, 14: Lane A4; Tāj «وقالَ عَلَيْهِ: افْترى»; al-Ṣiḥāḥ «أقْوَلْتَني ما لم أقُلْ، أي ادَّعَيْتَهُ على».', 0, 2, '[{"source": "lane_lexicon", "block": "blk_lane_5a009ed8b615f3a6", "page": "p.2994", "quote_en": "He lied, or said what was false, against him"}, {"source": "zabidi_taj_arus", "block": "blk_taj_3264a5bc1f368b7d", "page": "p.301", "quote_ar": "وقالَ عَلَيْهِ: افْترى"}, {"source": "jawhari_sihah", "block": "blk_sih_4771daf87fbd5b87", "page": "p.3577", "quote_ar": "ويقال: قَوَّلْتَني ما لم أقلْ، وأقْوَلْتَني ما لم أقُلْ، أي ادَّعَيْتَهُ على"}]', 0.9, 'lexicon_layers_2026_10_07', 'combined', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:cmb5', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'root', 'قول', 'cmb5', 'ما في النَّفس قبل أن يُلفَظ', 'what is held inside before it is spoken: a thought, a belief', 'ما في النفس', 'a thought held inside', 'combined rung 5: al-Rāghib’s second and third uses; Lisān (Ibn Jinnī) on why beliefs are called قَوْل.', 0, 3, '[{"source": "raghib_mufradat", "block": "blk_mfr_fe4b9a239dfee661", "page": "p.688", "quote_ar": "الثاني: يقال للمتصوّر في النّفس قبل الإبراز باللفظ: قَوْلٌ، فيقال: في نفسي قول لم أظهره"}, {"source": "raghib_mufradat", "block": "blk_mfr_4c345f860416b455", "page": "p.688", "quote_ar": "الثالث: للاعتقاد نحو فلان يقول بقول أبي حنيفة"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "فأَما تَجوُّزهم فِي تَسْمِيَتِهِمْ الِاعْتِقَادَاتِ وَالْآرَاءَ قَوْلًا فلأَن الِاعْتِقَادَ يخفَى فَلَا يُعْرَفُ إِلَّا بِالْقَوْلِ"}, {"source": "lane_lexicon", "block": "blk_lane_02833ba1a3d12d10", "page": "p.2994", "quote_en": "He asserted his belief in such a thing, as a doctrine or the like"}]', 0.85, 'lexicon_layers_2026_10_07', 'combined', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:cmb6', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'root', 'قول', 'cmb6', 'ما يَدُلُّ بلا لفظ', 'what shows a meaning without words: a sign, a state', 'الدلالة بلا لفظ', 'a sign without words', 'combined rungs 6–7: Lisān «وَقَدْ يُسْتَعْمَلُ القَوْل فِي غَيْرِ الإِنسان»; al-Rāghib’s fourth use; Lane A7.', 0, 4, '[{"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "وَقَدْ يُسْتَعْمَلُ القَوْل فِي غَيْرِ الإِنسان"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_0aeccb71071b1e73", "page": "p.4737", "quote_ar": "فإِن الْحَالَ آذَنَتْ بأَن لَوْ كَانَ لَهُمَا جَارِحَةُ نُطْقٍ لَقَالَتَا سَمْعًا وَطَاعَةً"}, {"source": "raghib_mufradat", "block": "blk_mfr_1284705f67eb7c34", "page": "p.688", "quote_ar": "الرابع: يقال للدّلالة على الشيء"}, {"source": "lane_lexicon", "block": "blk_lane_ea08b253f3a3fcdc", "page": "p.2995", "quote_en": "قَالَتِ العَيْنَانِ The eyes made a sign [as though saying...]"}]', 0.85, 'lexicon_layers_2026_10_07', 'combined', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:cmb10', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'root', 'قول', 'cmb10', 'القَوْلُ النافذ', 'a word that is carried out: the ruler’s word, a ruling', 'القول النافذ', 'a word carried out', 'combined rungs 8, 10, 11: the قَيْل (a king of Ḥimyar) is named so because his word is carried out; Lisān: قَوْل is used for حُكْم.', 0, 5, '[{"source": "jawhari_sihah", "block": "blk_sih_7623d8cb187886e5", "page": "p.3577", "quote_ar": "كأنه الذي له قَوْلٌ، أي يَنْفُذُ قولُهُ"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_871ff3b53c98e039", "page": "p.4737", "quote_ar": "سُمِّيَ الْمَلِكُ قَيْلًا لأَنه إِذا قَالَ قَوْلًا نفَذ قولُه"}, {"source": "raghib_mufradat", "block": "blk_mfr_443fe531dd240c1d", "page": "p.688", "quote_ar": "والْقَيْلُ: الملك من ملوك حمير سمّوه بذلك لكونه معتمدا على قوله ومقتدى به"}, {"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "يقولُ ما شاءَ فَيَنْفُذُ"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_c5e5faecffafd95c", "page": "p.4737", "quote_ar": "فإِن القَوْل يُسْتَعْمَلُ فِي مَعْنَى الحُكْم"}]', 0.85, 'lexicon_layers_2026_10_07', 'combined', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:say', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'dbc4c1228ac85ceb5398db8fff', 'say', 'نَطَقَ بكلام', 'to say: to put something into spoken words', 'قال', 'to say', 'قَالَ يَقُولُ قَوْلًا: أن ينطق المرء بكلام، مفردًا أو جملة.', 1, 1, '[{"source": "maqayis_lugha", "block": "blk_mqy_a7fc735a606ee41c", "page": "p.8", "quote_ar": "يُقال: قَالَ يقول قَولاً"}, {"source": "raghib_mufradat", "block": "blk_mfr_3ba74d8a48bcfaaa", "page": "p.688", "quote_ar": "أظهرها أن يكون للمركّب من الحروف المبرز بالنّطق، مفردا كان أو جملة"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "تَقُولُ: قَالَ يَقُولُ قَولًا، وَالْفَاعِلُ قَائِل، وَالْمَفْعُولُ مَقُول"}, {"source": "lane_lexicon", "block": "blk_lane_9e568e5dec78c750", "page": "p.2994", "quote_en": "meaning He said"}]', 0.95, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:say_against', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'dbc4c1228ac85ceb5398db8fff', 'say_against', 'قال على أحدٍ: افترى عليه', 'to say something about someone — mostly a lie (with عَلَى)', 'قال على', 'to say against', 'مع «على» يكون القول على أحدٍ، وأكثره كذب: «وقالَ عَلَيْهِ: افْترى». In the Qurʾān always «عَلَى ٱللَّهِ».', 0, 2, '[{"source": "lane_lexicon", "block": "blk_lane_5a009ed8b615f3a6", "page": "p.2994", "quote_en": "He lied, or said what was false, against him"}, {"source": "lane_lexicon", "block": "blk_lane_3688494a21994419", "page": "p.2994", "quote_en": "قال عَلَيْهِ, اِفْتَرَى عليه"}, {"source": "zabidi_taj_arus", "block": "blk_taj_3264a5bc1f368b7d", "page": "p.301", "quote_ar": "وقالَ عَلَيْهِ: افْترى"}, {"source": "zamakhshari", "ref": "QR:TE:e8c80b6ca8d2e116c9370800", "at": "7:33-33", "quote_ar": "وَأَنْ تَقُولُوا عَلَى اللَّهِ وأن تتقوّلوا عليه وتفتروا الكذب"}, {"source": "tabari", "ref": "QR:TE:1c791ed693b8c1dc8b840fdb", "at": "2:169-169", "quote_ar": "فهو ما كانوا يحرِّمون من البحائر والسوائب والوَصائل والحوامي، ويزعمون أن الله حرَّم ذلك"}]', 0.9, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:say_within', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'dbc4c1228ac85ceb5398db8fff', 'say_within', 'قال في نفسه: حدّث نفسه', 'to say inside oneself: a thought not spoken aloud', 'قال في نفسه', 'to say within', 'al-Rāghib reads 58:8 «وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ» as unspoken thought; Ibn ʿĀshūr reads it as saying it to one another.', 0, 3, '[{"source": "raghib_mufradat", "block": "blk_mfr_fe4b9a239dfee661", "page": "p.688", "quote_ar": "الثاني: يقال للمتصوّر في النّفس قبل الإبراز باللفظ: قَوْلٌ، فيقال: في نفسي قول لم أظهره"}, {"source": "raghib_mufradat", "block": "blk_mfr_7c173c85aa98cbe1", "page": "p.688", "quote_ar": "فجعل ما في اعتقادهم قولا"}, {"source": "ibn_ashur", "ref": "QR:TE:c6e7cb924012391b99fb7095", "at": "58:8-8 p.29", "quote_ar": "ومَعْنى يَقُولُونَ في أنْفُسِهِمْ يَقُولُ بَعْضُهم لِبَعْضٍ"}]', 0.7, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:say_wordless', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'dbc4c1228ac85ceb5398db8fff', 'say_wordless', 'القول بلا لفظ: إلهامٌ أو تسخير', 'to “say” without spoken words: God’s command that things obey, or an inspiration', 'القول بالتسخير', 'to say without words', 'al-Rāghib’s seventh use: الإلهام (18:86) and التسخير (41:11, 21:69). al-Zamakhsharī and Ibn ʿĀshūr agree on 41:11; al-Rāzī takes 18:86 as real speech.', 0, 4, '[{"source": "raghib_mufradat", "block": "blk_mfr_4637f03988cc61bf", "page": "p.688", "quote_ar": "السابع: في الإلهام"}, {"source": "raghib_mufradat", "block": "blk_mfr_ba31652f5d2bea11", "page": "p.688", "quote_ar": "فإنّ ذلك لم يكن بخطاب ورد عليه فيما روي وذكر، بل كان ذلك إلهاما فسماه قولا"}, {"source": "raghib_mufradat", "block": "blk_mfr_66784d64bcaf9ae7", "page": "p.688", "quote_ar": "إنّ ذلك كان بتسخير من الله تعالى لا بخطاب ظاهر ورد عليهما، وكذا قوله تعالى: قُلْنا يا نارُ كُونِي بَرْداً وَسَلاماً"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_fef310cd8dfb008d", "page": "p.4737", "quote_ar": "الْعَرَبُ تَجْعَلُ الْقَوْلَ عِبَارَةً عَنْ جَمِيعِ الأَفعال وتطلِقه عَلَى غَيْرِ الْكَلَامِ وَاللِّسَانِ"}, {"source": "zamakhshari", "ref": "QR:TE:e699c665aa429b0ae9e8ed22", "at": "41:9-12", "quote_ar": "من غير أن يحقق شيء من الخطاب والجواب"}, {"source": "ibn_ashur", "ref": "QR:TE:96a227fab748d33525c6d943", "at": "41:11-11 p.246", "quote_ar": "وهو قَوْلُ تَكْوِينٍ"}]', 0.75, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:words', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'b519a30933af9118c2a4bfb129', 'words', 'الكلام', 'words said; speech', 'القول', 'words, speech', 'القول: الكلام، أو كلُّ لفظ قاله اللسان تامًّا كان أو ناقصًا.', 1, 1, '[{"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "القَوْلُ: الكَلامُ، أو كُلُّ لَفْظٍ مَذَلَ به اللِسانُ، تامّاً أو ناقِصاً"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "القَوْل: الْكَلَامُ عَلَى التَّرْتِيبِ، وَهُوَ عِنْدَ المحقِّق كُلُّ لَفْظٍ قَالَ بِهِ اللِّسَانُ، تَامًّا كَانَ أَو نَاقِصًا"}, {"source": "raghib_mufradat", "block": "blk_mfr_3ba74d8a48bcfaaa", "page": "p.688", "quote_ar": "أظهرها أن يكون للمركّب من الحروف المبرز بالنّطق، مفردا كان أو جملة"}, {"source": "lane_lexicon", "block": "blk_lane_eead26a3e20fe2d5", "page": "p.2995", "quote_en": "A saying; something said: and speech, or diction"}]', 0.95, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:decree', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'b519a30933af9118c2a4bfb129', 'decree', 'حُكمُ الله الذي يقع لا محالة', 'God’s word of judgment that must come true', 'حق القول', 'the word that comes true', 'حَقَّ / سَبَقَ / وَقَعَ القَوْلُ: وجب حكم الله بالعذاب. al-Rāghib: «علم الله تعالى بهم وكلمته عليهم»; al-Ṭabarī: «وجب العقاب».', 0, 2, '[{"source": "raghib_mufradat", "block": "blk_mfr_7c1e8a7c41eedb59", "page": "p.688", "quote_ar": "لَقَدْ حَقَّ الْقَوْلُ عَلى أَكْثَرِهِمْ فَهُمْ لا يُؤْمِنُونَ"}, {"source": "raghib_mufradat", "block": "blk_mfr_7a288888eea40584", "page": "p.688", "quote_ar": "أي: علم الله تعالى بهم وكلمته عليهم"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_c5e5faecffafd95c", "page": "p.4737", "quote_ar": "فإِن القَوْل يُسْتَعْمَلُ فِي مَعْنَى الحُكْم"}, {"source": "tabari", "ref": "QR:TE:198c963a65b721d5e58852e3", "at": "36:6-7", "quote_ar": "لقد وجب العقاب على أكثرهم"}, {"source": "tabari", "ref": "QR:TE:fa8c5f4cfcbecfbb8f8c5283", "at": "32:12-13", "quote_ar": "وجب العذاب مني لهم"}]', 0.9, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:claims', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'b519a30933af9118c2a4bfb129', 'claims', 'ما يقوله الناس في أمرٍ', 'what people say about a matter — their clashing claims', 'قول مختلف', 'claims', 'At 51:8 «قَوۡلٖ مُّخۡتَلِفٖ»: al-Zamakhsharī and al-Ṭabarī — their clashing claims about the Prophet and the Qurʾān; al-Rāghib — the matter (the rising) talked about.', 0, 3, '[{"source": "raghib_mufradat", "block": "blk_mfr_d461b7cc771f3ede", "page": "p.688", "quote_ar": "أي: لفي أمر من البعث، فسمّاه قولا، فإنّ الْمَقُولَ فيه يسمّى قولا"}, {"source": "zamakhshari", "ref": "QR:TE:a42a09b890ba6224dda6e30c", "at": "51:7-9", "quote_ar": "قولهم في الرسول: ساحر وشاعر ومجنون، وفي القرآن: شعر وسحر وأساطير الأولين"}, {"source": "tabari", "ref": "QR:TE:afbe5f08f46d4123221f71f2", "at": "51:7-9", "quote_ar": "لفي قول مختلف في هذا القرآن، فمن مصدّق به ومكذّب"}]', 0.8, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:revelation', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'b519a30933af9118c2a4bfb129', 'revelation', 'القرآن، قولٌ يبلّغه رسول', 'the revealed word: the Quran, brought by a messenger', 'القول: القرآن', 'the revealed word', 'In 69:40, 81:19, 86:13, 73:5, 28:51, 23:68 the commentators take القَوْل as the Qurʾān. al-Rāghib: the word comes through the messenger from the One who sent him.', 0, 4, '[{"source": "raghib_mufradat", "block": "blk_mfr_ce8d61cff7b0c16d", "page": "p.688", "quote_ar": "وذلك أنّ القول الصادر إليك عن الرّسول يبلّغه إليك عن مرسل له"}, {"source": "tabari", "ref": "QR:TE:1ff5f1c82d880c9d529d8750", "at": "69:38-42", "quote_ar": "إن هذا القرآن لقول رسول كريم، وهو محمد"}, {"source": "zamakhshari", "ref": "QR:TE:1ef31fa23d794ec291479d2a", "at": "86:11-14", "quote_ar": "إِنَّهُ الضمير للقرآن"}, {"source": "zamakhshari", "ref": "QR:TE:affa6cb36e83810bd2831273", "at": "23:68-70", "quote_ar": "الْقَوْلَ القرآن"}]', 0.85, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:word_of_truth', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'b519a30933af9118c2a4bfb129', 'word_of_truth', 'عيسى: قولُ الحقّ وكلمةُ الله', 'Jesus as “the word of truth” (19:34) — as he is called God’s word', 'قول الحق', 'the word of truth', '19:34 «قَوۡلَ ٱلۡحَقِّ»: al-Rāghib and al-Zamakhsharī — Jesus is called قول as he is called كلمة; al-Ṭabarī — “this account is the true word”.', 0, 5, '[{"source": "raghib_mufradat", "block": "blk_mfr_e171ad7af5bacd79", "page": "p.688", "quote_ar": "فإنما سمّاه قول الحقّ تنبيها على ما قال"}, {"source": "raghib_mufradat", "block": "blk_mfr_4b7fc9493fbd4548", "page": "p.688", "quote_ar": "وتسميته قولا كتسميته كلمة في قوله: وَكَلِمَتُهُ أَلْقاها إِلى مَرْيَمَ"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_a90b58d943735a8f", "page": "p.4737", "quote_ar": "وَالْحَقُّ فِي هَذَا الْمَوْضِعِ يُرَادُ بِهِ الله تعالى ذِكرُه كأَنه قَالَ قَوْلَ اللهِ"}, {"source": "zamakhshari", "ref": "QR:TE:1a1247e6bedb45d024680054", "at": "19:34-34", "quote_ar": "وإنما قيل لعيسى «كلمة الله» و «قول الحق» لأنه لم يولد إلا بكلمة الله وحدها"}]', 0.7, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:sayer', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', '45cf5dfc844ffea30985b8699b', 'sayer', 'مَن يقول', 'one who says; a speaker', 'القائل', 'one who says', 'القائل: اسم الفاعل من قال.', 1, 1, '[{"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_7d46b992597c0b64", "page": "p.4737", "quote_ar": "تَقُولُ: قَالَ يَقُولُ قَولًا، وَالْفَاعِلُ قَائِل، وَالْمَفْعُولُ مَقُول"}, {"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "فهو قائِلٌ وقالٌ وقَؤُولٌ"}, {"source": "raghib_mufradat", "block": "blk_mfr_dabadc3b5dda90e9", "page": "p.688", "quote_ar": "أنا قَالُ كذا، أي: قَائِلُهُ"}]', 0.95, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:saying', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', '5d129109aa4d540e684518fd62', 'saying', 'القول', 'a saying; words spoken', 'القيل', 'a saying', 'القِيل والقَوْل واحد (al-Rāghib, on 4:122).', 1, 1, '[{"source": "raghib_mufradat", "block": "blk_mfr_a5a15ef673670b0d", "page": "p.688", "quote_ar": "القَوْلُ والقِيلُ واحد"}, {"source": "fayyumi_misbah_munir", "block": "blk_msb_1010ee9d1de9df2a", "page": "p.2555", "quote_ar": "وَالْقَالُ وَالْقِيلُ اسْمَانِ مِنْهُ لَا مَصْدَرَانِ"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_a9abb665776f8d2a", "page": "p.4737", "quote_ar": "قَالَ يَقُولُ قَوْلًا وقِيلًا وقَوْلةً ومَقالًا ومَقالةً"}, {"source": "tabari", "ref": "QR:TE:cef669bb9f8e68b930ef1540", "at": "43:87-88", "quote_ar": "هذا قول نبيكم عليه الصلاة والسلام يشكو قومه إلى ربه"}]', 0.9, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:forge', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'fb70ffa1155199876c5f8390a9', 'forge', 'تقوّل عليه: افترى عليه ما لم يقل', 'to make up words and say someone said them', 'التقوّل', 'to make up a saying', 'تَقَوَّلَ قَوْلًا: ابتدعه كذبًا؛ تقوّل عليه: قال عليه ما لم يقل.', 1, 1, '[{"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "وتَقَوَّلَ قَوْلاً: ابتَدَعه كذِباً"}, {"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_21f08641a3972f36", "page": "p.4737", "quote_ar": "وتَقَوَّلَ قَوْلًا: ابتدَعه كذِباً. وتَقَوَّلَ فُلَانٌ عليَّ بَاطِلًا أَي قَالَ عَليَّ مَا لَمْ أَكن قلتُ وَكَذِبَ عليَّ؛ وَمِنْهُ قَوْلُهُ تَعَالَى: وَلَوْ تَقَوَّلَ عَلَيْنا بَعْضَ الْأَقاوِيلِ"}, {"source": "fayyumi_misbah_munir", "block": "blk_msb_5943421122314433", "page": "p.2555", "quote_ar": "وَتَقَوَّلَ الرَّجُلُ عَلَى زَيْدٍ مَا لَمْ يَقُلْ ادَّعَى عَلَيْهِ مَا لَا حَقِيقَةَ لَهُ"}, {"source": "jawhari_sihah", "block": "blk_sih_1cbadbf0a1719af6", "page": "p.3577", "quote_ar": "وتقول عليه، أي كذب عليه"}, {"source": "lane_lexicon", "block": "blk_lane_560ca945c2187d1a", "page": "p.2995", "quote_en": "تَقَوَّلَ عَلَيْهِ He lied against him"}, {"source": "zamakhshari", "ref": "QR:TE:c80f8c7e5d34d7759b86bc0a", "at": "52:30-43", "quote_ar": "تَقَوَّلَهُ اختلقه من تلقاء نفسه"}, {"source": "tabari", "ref": "QR:TE:5939fe68275fc9bcdb17cab4", "at": "52:32-34", "quote_ar": "أم يقول هؤلاء المشركون: تقوّل محمد هذا القرآن وتخلَّقه"}]', 0.95, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
INSERT INTO ar_ling_root_sense (id, root_id, root_norm, scope_level, scope_key, sense_key, gloss_ar, gloss_en, label_ar, label_en, definition_md, is_core, sort_order, provenance_json, confidence, generated_by, source_slug, status, display_json) VALUES ('SNS:قول:sayings', '58adcb34a9f5ad358ca4df9c7e', 'قول', 'lemma', 'd2d1c95d37456b22f8850bdb7f', 'sayings', 'جمع الجمع من القول', 'sayings — in 69:44, made-up sayings', 'الأقاويل', 'sayings', 'أقاويل جمع أقوال (Lisān, al-Qāmūs). al-Zamakhsharī: the made-up sayings are called أقاويل to belittle them.', 1, 1, '[{"source": "ibn_manzur_lisan_arab", "block": "blk_lsn_a9abb665776f8d2a", "page": "p.4737", "quote_ar": "وَالْجَمْعُ أَقْوال، وأَقاوِيل جَمْعُ الْجَمْعِ"}, {"source": "qamus_muhit", "block": "blk_qms_dbb270b2b54cca7d", "page": "no printed page", "quote_ar": "ج: أقْوالٌ. جج: أقاويلٌ"}, {"source": "zamakhshari", "ref": "QR:TE:176eecc4c90171accb45a2a0", "at": "69:44-52", "quote_ar": "وسمى الأقوال المتقولة «أقاويل» تصغيرا بها وتحقيرا"}, {"source": "tabari", "ref": "QR:TE:ee28f1682138094ca97c2e5f", "at": "69:43-46", "quote_ar": "الباطلة، وتكذب علينا"}]', 0.9, 'lexicon_layers_2026_10_07', 'kmaps_sense_map', 'live', NULL);
