INSERT INTO ar_ling_sense_attestation (id, target_type, target_id, source_slug, quote_ar, quote_en, locator, chunk_ref, agreement, confidence, status, block_id) VALUES ('ATT:S:SNS:قول:cmb1:ibn_manzur_lisan_arab', 'sense', 'SNS:قول:cmb1', 'ibn_manzur_lisan_arab', 'القَوْل: الْكَلَامُ عَلَى التَّرْتِيبِ، وَهُوَ عِنْدَ المحقِّق كُلُّ لَفْظٍ قَالَ بِهِ اللِّسَانُ، تَامًّا كَانَ أَو نَاقِصًا', NULL, 'p.4737 · blk_lsn_7d46b992597c0b64', 're_lsn_742c2383f405f8ae', 'supports', 0.85, 'live', 'blk_lsn_7d46b992597c0b64');
