INSERT INTO ar_ling_sense_attestation (id, target_type, target_id, source_slug, quote_ar, quote_en, locator, chunk_ref, agreement, confidence, status, block_id) VALUES ('ATT:S:SNS:قول:cmb3:jawhari_sihah', 'sense', 'SNS:قول:cmb3', 'jawhari_sihah', 'ويقال: قَوَّلْتَني ما لم أقلْ، وأقْوَلْتَني ما لم أقُلْ، أي ادَّعَيْتَهُ على', NULL, 'p.3577 · blk_sih_4771daf87fbd5b87', 're_sih_1cd1ac2a2ebe3997', 'supports', 0.85, 'live', 'blk_sih_4771daf87fbd5b87');
INSERT INTO ar_ling_sense_attestation (id, target_type, target_id, source_slug, quote_ar, quote_en, locator, chunk_ref, agreement, confidence, status, block_id) VALUES ('ATT:S:SNS:قول:cmb5:raghib_mufradat', 'sense', 'SNS:قول:cmb5', 'raghib_mufradat', 'الثاني: يقال للمتصوّر في النّفس قبل الإبراز باللفظ: قَوْلٌ، فيقال: في نفسي قول لم أظهره', NULL, 'p.688 · blk_mfr_fe4b9a239dfee661', 're_mfr_d52610d4b4421942', 'supports', 0.85, 'live', 'blk_mfr_fe4b9a239dfee661');
