INSERT INTO ar_ling_sense_attestation (id, target_type, target_id, source_slug, quote_ar, quote_en, locator, chunk_ref, agreement, confidence, status, block_id) VALUES ('ATT:S:SNS:قول:forge:ibn_manzur_lisan_arab', 'sense', 'SNS:قول:forge', 'ibn_manzur_lisan_arab', 'وتَقَوَّلَ قَوْلًا: ابتدَعه كذِباً. وتَقَوَّلَ فُلَانٌ عليَّ بَاطِلًا أَي قَالَ عَليَّ مَا لَمْ أَكن قلتُ وَكَذِبَ عليَّ؛ وَمِنْهُ قَوْلُهُ تَعَالَى: وَلَوْ تَقَوَّلَ عَلَيْنا بَعْضَ الْأَقاوِيلِ', NULL, 'p.4737 · blk_lsn_21f08641a3972f36', 're_lsn_742c2383f405f8ae', 'supports', 0.85, 'live', 'blk_lsn_21f08641a3972f36');
