INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:say', 'lemma', 'dbc4c1228ac85ceb5398db8fff', 'قول', 'speaking>saying', 'SNS:قول:say', 'النُّطق ← القَوْل', 'speaking aloud → to say', 1, 1, 0.9, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:speech', 'lemma', 'b519a30933af9118c2a4bfb129', 'قول', 'speaking>words_said', 'SNS:قول:words', 'النُّطق ← الكلام المقول', 'speaking aloud → words said, speech', 1, 1, 0.9, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:decree', 'lemma', 'b519a30933af9118c2a4bfb129', 'قول', 'speaking>word_carried_out>decree', 'SNS:قول:decree', 'النُّطق ← القول النافذ ← حَقَّ القولُ', 'speaking aloud → a word that is carried out → God’s word that must come true', 0, 1, 0.85, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:sayer', 'lemma', '45cf5dfc844ffea30985b8699b', 'قول', 'speaking>sayer', 'SNS:قول:sayer', 'النُّطق ← القائل', 'speaking aloud → one who says', 1, 1, 0.9, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:saying', 'lemma', '5d129109aa4d540e684518fd62', 'قول', 'speaking>a_saying', 'SNS:قول:saying', 'النُّطق ← القِيل', 'speaking aloud → a saying', 1, 1, 0.9, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:forge', 'lemma', 'fb70ffa1155199876c5f8390a9', 'قول', 'speaking>saying_against>forging', 'SNS:قول:forge', 'النُّطق ← القول على أحدٍ ← التقوّل', 'speaking aloud → saying something false against someone → making up words and pinning them on someone', 1, 1, 0.9, 'live', '58adcb34a9f5ad358ca4df9c7e');
