INSERT INTO ar_ling_sense_arc (id, scope_level, scope_key, root_norm, arc_key, terminal_sense_id, arc_ar, arc_en, is_primary, is_synthesis, confidence, status, root_id) VALUES ('ARC:قول:main', 'root', 'قول', 'قول', 'speaking>held_inside>without_words>carried_out', 'SNS:قول:cmb10', 'النُّطقُ باللسان ← ما في النفس ← ما يدلّ بلا لفظ ← القولُ النافذ', 'speaking aloud → a thought held inside → a sign without words → a word that is carried out', 1, 1, 0.85, 'live', '58adcb34a9f5ad358ca4df9c7e');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:say:1', 'ARC:قول:say', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:say:2', 'ARC:قول:say', 2, 'SNS:قول:say', 'the Qurʾān’s plain sense, 1,618 uses');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:speech:1', 'ARC:قول:speech', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:speech:2', 'ARC:قول:speech', 2, 'SNS:قول:words', 'the noun: what is said');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:decree:1', 'ARC:قول:decree', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:decree:2', 'ARC:قول:decree', 2, 'SNS:قول:cmb10', 'combined rungs 8, 10, 11: the قَيْل whose word is carried out; قول used for حُكم');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:decree:3', 'ARC:قول:decree', 3, 'SNS:قول:decree', 'Qurʾān: حَقَّ / سَبَقَ / وَقَعَ القَوْلُ (13 uses)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:sayer:1', 'ARC:قول:sayer', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:sayer:2', 'ARC:قول:sayer', 2, 'SNS:قول:sayer', 'the doer noun of قَالَ');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:saying:1', 'ARC:قول:saying', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:saying:2', 'ARC:قول:saying', 2, 'SNS:قول:saying', 'another noun for what is said');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:forge:1', 'ARC:قول:forge', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:forge:2', 'ARC:قول:forge', 2, 'SNS:قول:cmb3', 'combined rungs 3, 14: قال عليه = افترى عليه');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:forge:3', 'ARC:قول:forge', 3, 'SNS:قول:forge', 'Form V: the made-up saying (52:33, 69:44)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:sayings:1', 'ARC:قول:sayings', 1, 'SNS:قول:cmb1', 'combined rungs 1–2 (Ibn Fāris, al-Rāghib)');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:قول:sayings:2', 'ARC:قول:sayings', 2, 'SNS:قول:sayings', 'plural of أَقْوَال; at 69:44 the forged sayings');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('STP:قول:1', 'ARC:قول:main', 1, 'SNS:قول:cmb1', 'Every book opens on speech: Ibn Fāris «وهو القَول من النُّطق».');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('STP:قول:2', 'ARC:قول:main', 2, 'SNS:قول:cmb5', 'A thought or belief is called قَوْل because only speech shows it (Ibn Jinnī in Lisān; al-Rāghib’s 2nd and 3rd uses).');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('STP:قول:3', 'ARC:قول:main', 3, 'SNS:قول:cmb6', 'Then what speaks without a tongue: eyes, a full pool, a state (Lisān; al-Rāghib’s 4th use; Lane A7).');
INSERT INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('STP:قول:4', 'ARC:قول:main', 4, 'SNS:قول:cmb10', 'The قَيْل is the king whose word is carried out; so قَوْل also means a ruling (al-Ṣiḥāḥ, Lisān, al-Rāghib).');
