INSERT INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status) VALUES ('ARC:قول:qala:ala', 'قول', 'dbc4c1228ac85ceb5398db8fff', NULL, 'قَالَ عَلَى + مقول', 'على', 1, 13, '["2:80", "2:169", "3:75", "3:78", "4:171", "6:93", "7:28", "7:33", "7:105", "7:169", "10:68", "72:4", "72:5"]', 'القول ← القول على أحدٍ ← الافتراء عليه', 'say → say about someone → pin a lie on him', 'In all 13 uses the one spoken about is God (عَلَى ٱللَّهِ). 3:75 counts here, though its word tags in km_quran are shifted by one.', NULL, '[{"kind": "object_semantics", "label": "a lie, or what they do not know", "refs": ["2:80", "2:169", "3:75", "3:78", "6:93", "7:28", "7:33", "10:68", "72:4", "72:5"]}, {"kind": "object_semantics", "label": "nothing but the truth (a ban or a vow)", "refs": ["4:171", "7:105", "7:169"]}]', '["lex:lane_lexicon:blk_lane_5a009ed8b615f3a6", "lex:zabidi_taj_arus:blk_taj_3264a5bc1f368b7d", "tafsir:zamakhshari:7:33:QR:TE:e8c80b6ca8d2e116c9370800", "mir:VI:288"]', 0.9, 'live');
INSERT INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status) VALUES ('ARC:قول:taqawwala:direct', 'قول', 'fb70ffa1155199876c5f8390a9', NULL, 'تَقَوَّلَ + مفعول', NULL, 1, 1, '["52:33"]', 'القول ← اختلاقُ القول', 'say → make up the saying itself', 'The object is the made-up saying (here the Qurʾān, as the deniers claim).', NULL, NULL, '["lex:qamus_muhit:blk_qms_dbb270b2b54cca7d", "tafsir:zamakhshari:52:33:QR:TE:c80f8c7e5d34d7759b86bc0a"]', 0.9, 'live');
INSERT INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status) VALUES ('ARC:قول:taqawwala:ala', 'قول', 'fb70ffa1155199876c5f8390a9', NULL, 'تَقَوَّلَ عَلَى + مفعول', 'على', 1, 1, '["69:44"]', 'القول ← التقوّل على أحدٍ', 'make up a saying → and put it on someone', 'عَلَى names the one the made-up words are pinned on (here God).', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_21f08641a3972f36", "lex:lane_lexicon:blk_lane_560ca945c2187d1a", "mir:VI:288"]', 0.9, 'live');
INSERT INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, fluent_en, note_en, is_primary, source_ref, seq, text_ar) VALUES ('AEX:7:33:qala_ala', 'ARC:قول:qala:ala', '7:33', 7, 33, 'and that you say about God what you do not know', 'al-Zamakhsharī: to make up lies against Him', 1, 'tafsir:zamakhshari:7:33:QR:TE:e8c80b6ca8d2e116c9370800', 1, 'وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ');
INSERT INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, fluent_en, note_en, is_primary, source_ref, seq, text_ar) VALUES ('AEX:3:75:qala_ala', 'ARC:قول:qala:ala', '3:75', 3, 75, 'they knowingly tell lies about God', NULL, 0, NULL, 2, 'وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ');
INSERT INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, fluent_en, note_en, is_primary, source_ref, seq, text_ar) VALUES ('AEX:4:171:qala_ala', 'ARC:قول:qala:ala', '4:171', 4, 171, 'and say nothing about God but the truth', 'the same frame, used to forbid', 0, NULL, 3, 'وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ');
INSERT INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, fluent_en, note_en, is_primary, source_ref, seq, text_ar) VALUES ('AEX:52:33:taqawwala', 'ARC:قول:taqawwala:direct', '52:33', 52, 33, 'or do they say, “He made it up”?', 'al-Zamakhsharī: made it up himself', 1, 'tafsir:zamakhshari:52:33:QR:TE:c80f8c7e5d34d7759b86bc0a', 1, 'أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ');
INSERT INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, fluent_en, note_en, is_primary, source_ref, seq, text_ar) VALUES ('AEX:69:44:taqawwala', 'ARC:قول:taqawwala:ala', '69:44', 69, 44, 'had he made up sayings and put them on Us', NULL, 1, 'tafsir:tabari:69:44:QR:TE:ee28f1682138094ca97c2e5f', 1, 'وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ');
