INSERT INTO ar_ling_root_lemma_furuq_evidence (id, set_id, member_id, lemma_id, qr_ref, surah, ayah, word_index, arabic_quote, evidence_type, confidence, validation_status, note_md) VALUES ('NSE:A809D3ED', 'NS:TO:TO_INVENT_STORIES_SLANDER', 'NSM:TO:TO_INVENT_STORIES_SLANDER:XA1A6B9DC', '9927a37656af1057f2962c9f03', 'QR:38:7:10', 38, 7, 10, 'إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ', 'quran_usage', 'high', 'checked', 'needle: ان هذا الا اختلق');
INSERT INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:TO:TO_INVENT_STORIES_SLANDER:contrast', 'NS:TO:TO_INVENT_STORIES_SLANDER', 'kmaps_synth', 'contrast', 'contrast', 'تَقَوَّلَ puts made-up words in someone’s mouth; اِفْتَرَى cuts a lie out of nothing, and is also used for setting up partners with God; خَرَصَ talks by guesswork, with no knowledge; اخْتِلَاق is a story shaped like a made thing. — al-Rāghib pp. 634, 279, 296; al-Qāmūs (قول); al-Miṣbāḥ pp. 2555, 2316, 893; Lane pp. 2995, 2391, 722, 800', 'high');
INSERT INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:7FEE05D3', 'NSM:SPEECH:SPEECH:XC805B2DD', 'raghib_mufradat', 'blk_mfr_3ba74d8a48bcfaaa', 'gloss_support', 'أظهرها أن يكون للمركّب من الحروف المبرز بالنّطق، مفردا كان أو جملة', 'direct_source', 'high', 'p.688');
INSERT INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:DE8276DF', 'NSM:SPEECH:SPEECH:XC805B2DD', 'ibn_manzur_lisan_arab', 'blk_lsn_7d46b992597c0b64', 'gloss_support', 'القَوْل: الْكَلَامُ عَلَى التَّرْتِيبِ، وَهُوَ عِنْدَ المحقِّق كُلُّ لَفْظٍ قَالَ بِهِ اللِّسَانُ، تَامًّا كَانَ أَو نَاقِصًا', 'direct_source', 'high', 'p.4737');
