INSERT INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:53027EEE', 'NSM:SPEECH:SPEECH:X259D7F07', 'maqayis_lugha', 'blk_mqy_fae5380e7edf7a04', 'gloss_support', 'ثمَّ يتَّسِعون فيسمُّون اللفظةَ الواحدة المُفهِمَةَ كلمة، والقِصَّةَ كلمة، والقصيدةَ بطولها كلمة', 'direct_source', 'high', 'p.31');
INSERT INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:7135DBF5', 'NSM:SPEECH:SPEECH:X259D7F07', 'raghib_mufradat', 'blk_mfr_91fcc160f21fd3ce', 'gloss_support', 'فَالْكَلِمَةُ هاهنا القضيّة، فكلّ قضيّة تسمّى كلمة سواء كان ذلك مقالا أو فعالا', 'direct_source', 'high', 'p.722');
