INSERT INTO ar_ling_root_lemma_furuq_evidence (id, set_id, member_id, lemma_id, qr_ref, surah, ayah, word_index, arabic_quote, evidence_type, confidence, validation_status, note_md) VALUES ('NSE:9F1D95AB', 'NS:SPEECH:SPEECH', 'NSM:SPEECH:SPEECH:X259D7F07', '7334b4236d14fcfe9b7d434148', 'QR:18:5:9', 18, 5, 9, 'كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ', 'quran_usage', 'high', 'checked', 'needle: كبرت كلمه تخرج من افوههم');
INSERT INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:SPEECH:SPEECH:contrast', 'NS:SPEECH:SPEECH', 'kmaps_synth', 'contrast', 'contrast', 'قَوْل is any words spoken, one word or a sentence; حَدِيث is talk or news that is told and passed on, coming bit by bit; كَلِمَة is one unit of speech — a word, or a whole saying or ruling taken as one. — al-Rāghib pp. 688, 722; Maqāyīs (حدث, كلم); al-Ṣiḥāḥ p.544; Lane pp. 2995, 529, 3002', 'high');
INSERT INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, note, sort_order, source_ref, status, root_id, confidence, generated_by, antonym_ur, note_ar, note_ur, note_en, display_json, antonym_root_id, lemma_id, for_word_ar, for_word_en) VALUES ('DID:قول:فعل', 'قول', 'فَعَلَ', 'فعل', 'to do', 'contrast', NULL, 1, 'al-Ṭabarī QR:TE:7e2f6354ae2fd435fb4bd8c2 at 61:1-3 («لم تقولون القول الذي لا تصدّقونه بالعمل، فأعمالكم مخالفة أقوالكم»); Qurʾān 61:2–3. No lexicon in the corpus states it.', 'live', '58adcb34a9f5ad358ca4df9c7e', 0.7, 'source_stated', 'کرنا', 'القولُ يُخالِفُه الفعلُ: لِمَ تقولون ما لا تفعلون', NULL, 'Saying ↔ doing: “Why do you say what you do not do?” (61:2). al-Ṭabarī: their deeds go against their words.', '{"quran": [{"surah": 61, "ayah": 2, "needle": "لم تقولون ما لا تفعلون"}]}', 'd6ce0581a586f13606ff3cb405', 'dbc4c1228ac85ceb5398db8fff', 'قَالَ', 'to say');
INSERT INTO ar_ling_root_dna (root_norm, root_id, radicals_json, headline_ar, headline_en, headline_ur, core_ar, core_en, core_ur, poles_json, senses_json, family_json, anchor_ref, anchor_word_ar, provenance_json, confidence, synthesis_version, status, picture_en, picture_ar) VALUES ('قول', '58adcb34a9f5ad358ca4df9c7e', '["ق", "و", "ل"]', 'جَذْرُ النُّطْق', 'The root of speaking', NULL, 'النُّطقُ بالكلام', 'speaking: putting words into sound', NULL, '[{"pole": "spoken", "label_ar": "القولُ باللسان", "label_en": "said aloud"}, {"pole": "unspoken", "label_ar": "ما في النفس", "label_en": "held inside"}, {"pole": "carried_out", "label_ar": "القولُ النافذ", "label_en": "a word carried out"}]', '[{"k": "speaking"}, {"k": "thought"}, {"k": "sign"}, {"k": "ruling"}, {"k": "forging"}]', '["I قَالَ", "V تَقَوَّلَ", "قَوْل", "قِيل", "قَائِل", "أَقَاوِيل"]', '2:30', 'قَالَ', '["maqayis_lugha", "raghib_mufradat", "jawhari_sihah", "ibn_manzur_lisan_arab", "qamus_muhit", "fayyumi_misbah_munir", "lane_lexicon"]', 0.85, 'v1', 'live', 'Words coming off the tongue — and, from there, a thought, a sign, or a command that is carried out.', 'نُطْقُ اللِّسَانِ بِالكَلَامِ');
INSERT INTO ar_ling_root_tatawwur (id, root_norm, stage_no, stage_ar, stage_en, note_en, source_ref, source_slug, status, root_id, confidence, generated_by) VALUES ('TAT:قول:1', 'قول', 1, 'النُّطقُ باللسان', 'speaking with the tongue', 'Every book opens here. Ibn Fāris: one sound root, «وهو القَول من النُّطق»; al-Rāghib: letters joined and spoken, a word or a sentence.', 'Maqāyīs blk_mqy_a7fc735a606ee41c p.8; al-Rāghib blk_mfr_3ba74d8a48bcfaaa p.688', 'kmaps_tatawwur', 'live', '58adcb34a9f5ad358ca4df9c7e', 0.95, 'kmaps_synthesis');
INSERT INTO ar_ling_root_tatawwur (id, root_norm, stage_no, stage_ar, stage_en, note_en, source_ref, source_slug, status, root_id, confidence, generated_by) VALUES ('TAT:قول:2', 'قول', 2, 'ما في النفس والاعتقاد', 'a thought or belief held inside', 'al-Rāghib’s second and third uses; Ibn Jinnī in Lisān: a belief is called قَوْل because only speech makes it known.', 'al-Rāghib blk_mfr_fe4b9a239dfee661 p.688; Lisān blk_lsn_7d46b992597c0b64 p.4737', 'kmaps_tatawwur', 'live', '58adcb34a9f5ad358ca4df9c7e', 0.85, 'kmaps_synthesis');
INSERT INTO ar_ling_root_tatawwur (id, root_norm, stage_no, stage_ar, stage_en, note_en, source_ref, source_slug, status, root_id, confidence, generated_by) VALUES ('TAT:قول:3', 'قول', 3, 'ما يدلّ بلا لسان', 'what speaks without a tongue: a sign, a state', 'Lisān: قَوْل is used of more than people — eyes, a full pool, rain clouds — because the state speaks; al-Rāghib’s fourth use; Lane A7.', 'Lisān blk_lsn_7d46b992597c0b64 p.4737; Lisān blk_lsn_0aeccb71071b1e73 p.4737; al-Rāghib blk_mfr_1284705f67eb7c34 p.688', 'kmaps_tatawwur', 'live', '58adcb34a9f5ad358ca4df9c7e', 0.85, 'kmaps_synthesis');
INSERT INTO ar_ling_root_tatawwur (id, root_norm, stage_no, stage_ar, stage_en, note_en, source_ref, source_slug, status, root_id, confidence, generated_by) VALUES ('TAT:قول:4', 'قول', 4, 'القولُ النافذ', 'a word that is carried out: the ruler, the ruling', 'The قَيْل (a king of Ḥimyar) is named for his word that is carried out (al-Ṣiḥāḥ, Lisān, al-Rāghib, al-Qāmūs); Lisān: قَوْل is used for حُكْم. The Qurʾān’s «حَقَّ القَوْلُ» stands on this rung.', 'al-Ṣiḥāḥ blk_sih_7623d8cb187886e5 p.3577; Lisān blk_lsn_871ff3b53c98e039 p.4737; Lisān blk_lsn_c5e5faecffafd95c p.4737', 'kmaps_tatawwur', 'live', '58adcb34a9f5ad358ca4df9c7e', 0.85, 'kmaps_synthesis');
